BEGIN;
CREATE TABLE IF NOT EXISTS calculation.bank_profit_result(run_id uuid PRIMARY KEY REFERENCES calculation.run(run_id),theoretical_shareholder_profit numeric(30,12) NOT NULL CHECK(theoretical_shareholder_profit>0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),calculated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS risk.voluntary_support(support_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES calculation.run(run_id),support_type text NOT NULL CHECK(support_type IN('RESERVE_RELEASE','TANAZUL')),amount numeric(30,12) NOT NULL CHECK(amount>0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),source_reference text NOT NULL,approval_id text NOT NULL REFERENCES workflow.approval_action(idempotency_key),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(run_id,support_type,source_reference));
CREATE TABLE IF NOT EXISTS risk.consolidated_dcr(run_id uuid PRIMARY KEY REFERENCES calculation.run(run_id),theoretical_shareholder_profit numeric(30,12) NOT NULL CHECK(theoretical_shareholder_profit>0),reserve_support numeric(30,12) NOT NULL CHECK(reserve_support>=0),tanazul_support numeric(30,12) NOT NULL CHECK(tanazul_support>=0),total_voluntary_support numeric(30,12) NOT NULL,consolidated_dcr numeric(30,12) NOT NULL CHECK(consolidated_dcr>=0),calculated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(total_voluntary_support=reserve_support+tanazul_support),CHECK(consolidated_dcr=round(total_voluntary_support/theoretical_shareholder_profit,12)));
ALTER TABLE risk.stress_scenario ADD COLUMN IF NOT EXISTS source_run_id uuid REFERENCES calculation.run(run_id),ADD COLUMN IF NOT EXISTS full_engine_rerun boolean NOT NULL DEFAULT false,ADD COLUMN IF NOT EXISTS output_checksum_sha256 text CHECK(output_checksum_sha256 IS NULL OR output_checksum_sha256~'^[a-f0-9]{64}$');
ALTER TABLE risk.stress_scenario ADD CONSTRAINT completed_full_stress_has_lineage CHECK(NOT full_engine_rerun OR(source_run_id IS NOT NULL AND output_checksum_sha256 IS NOT NULL));
CREATE OR REPLACE FUNCTION risk.reject_dcr_support_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'DCR support evidence and consolidated results are immutable';END;$$;
DROP TRIGGER IF EXISTS voluntary_support_immutable ON risk.voluntary_support;CREATE TRIGGER voluntary_support_immutable BEFORE UPDATE OR DELETE ON risk.voluntary_support FOR EACH ROW EXECUTE FUNCTION risk.reject_dcr_support_mutation();
DROP TRIGGER IF EXISTS consolidated_dcr_immutable ON risk.consolidated_dcr;CREATE TRIGGER consolidated_dcr_immutable BEFORE UPDATE OR DELETE ON risk.consolidated_dcr FOR EACH ROW EXECUTE FUNCTION risk.reject_dcr_support_mutation();
DROP TRIGGER IF EXISTS bank_profit_result_immutable ON calculation.bank_profit_result;CREATE TRIGGER bank_profit_result_immutable BEFORE UPDATE OR DELETE ON calculation.bank_profit_result FOR EACH ROW EXECUTE FUNCTION risk.reject_dcr_support_mutation();
COMMIT;
